EN[1] = dict(
 headline="Progress on the Thai–Chinese high-speed railway and the subcommittees' work",
 summary="The committee heard progress reports from its subcommittees. The subcommittee studying the high-speed railway linking three airports and phase 1 of the Thai–Chinese high-speed railway (Bangkok–Nakhon Ratchasima) reported that the State Railway of Thailand still faces several obstacles, such as permission to use government land, land expropriation, design changes and delays in some contracts. Contracts 3-1 and 3-2 are awaiting permission to use forest land in Saraburi, and expropriation under contract 3-1 has only 3 plots left, with the land expected to be handed over by February 2569. The committee also heard progress from the subcommittees on water transport and on accident prevention.",
 items=["Progress of phase 1 of the Thai–Chinese high-speed railway and the high-speed railway linking three airports",
        "Progress of the other subcommittees"])
EN[2] = dict(
 headline="Crane parts from high-speed railway construction fall on a train at Sikhio, and the Rama 2 Road incident",
 summary="The committee invited the agencies concerned to explain the incident of 14 January 2569, when the front support of a launching girder crane of the Thai–Chinese high-speed railway project, weighing about 40–50 tonnes, fell onto a passenger train in Sikhio District, Nakhon Ratchasima, while the contractor was moving the equipment to its next position. 30 people died and 69 were injured. The agencies reported initial compensation for the families of those who died, about 1,773,000 baht per person in total, from the contractor, the project's insurer and the State Railway of Thailand. The committee also heard the Department of Highways on the collapse of the Bang Khun Thian–Ban Phaeo elevated road (Motorway 82) in Mueang Samut Sakhon District on 15 January 2569, in which 2 workers died and 2 were injured. Experts' initial checks found a progressive collapse of the structure. The committee stressed raising safety standards in infrastructure construction.",
 items=["Crane parts from high-speed railway construction falling onto a passenger train, Sikhio District, Nakhon Ratchasima (14 January 2569)",
        "Collapse of the Bang Khun Thian–Ban Phaeo elevated road (M82), Mueang Samut Sakhon District (15 January 2569)"])
